const data = $json;

let result = data.output;

if (typeof result !== "string") {
  result = JSON.stringify(result);
}

result = result
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(result);
} catch (error) {
  throw new Error("Invalid JSON returned by AI");
}

return {
  json: parsed
};

const items = $input.all();

const requiredFields = [
  "Month",
  "Revenue",
  "Target_Revenue"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {

  const data = item.json;

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  const revenue = Number(data.Revenue);

  const target = Number(data.Target_Revenue);

  if (
    missingFields.length === 0 &&
    !isNaN(revenue) &&
    !isNaN(target)
  ) {

    validItems.push({
      Month: data.Month,
      Revenue: revenue,
      Target_Revenue: target
    });

  } else {

    invalidItems.push({
      month: data.Month || "Unknown",
      missing_fields: missingFields
    });

  }
}

return [
  {
    json: {
      data_valid: invalidItems.length === 0,
      total_records: items.length,
      valid_records: validItems.length,
      invalid_records: invalidItems.length,
      invalid_details: invalidItems,
      revenue_data: validItems
    }
  }
];

const data = $json.revenue_data;

if (data.length < 2) {
  throw new Error("At least 2 months of revenue data are required.");
}

let growthRates = [];

for (let i = 1; i < data.length; i++) {

  const previousRevenue = Number(data[i - 1].Revenue);
  const currentRevenue = Number(data[i].Revenue);

  if (previousRevenue > 0) {

    const growth =
      ((currentRevenue - previousRevenue) / previousRevenue) * 100;

    growthRates.push(growth);
  }
}

const averageGrowth =
  growthRates.reduce((sum, value) => sum + value, 0)
  / growthRates.length;

const latestRevenue =
  Number(data[data.length - 1].Revenue);

const latestMonth =
  data[data.length - 1].Month;

let trend;

if (averageGrowth > 2) {
  trend = "INCREASING";
} else if (averageGrowth < -2) {
  trend = "DECREASING";
} else {
  trend = "STABLE";
}

return [
  {
    json: {
      revenue_data: data,
      latest_month: latestMonth,
      latest_revenue: latestRevenue,
      average_growth: Number(averageGrowth.toFixed(2)),
      trend: trend,
      growth_rates: growthRates.map(
        value => Number(value.toFixed(2))
      )
    }
  }
];

const latestRevenue = Number($json.latest_revenue);
const averageGrowth = Number($json.average_growth);

const forecastRevenue =
  latestRevenue * (1 + averageGrowth / 100);

const forecastMonth = "Next Month";

const latestTarget =
  Number(
    $json.revenue_data[
      $json.revenue_data.length - 1
    ].Target_Revenue
  );

const forecastVsTarget =
  forecastRevenue - latestTarget;

let forecastStatus;

if (forecastRevenue >= latestTarget) {
  forecastStatus = "ABOVE TARGET";
} else {
  forecastStatus = "BELOW TARGET";
}

return [
  {
    json: {
      ...$json,

      forecast_month: forecastMonth,

      forecast_revenue:
        Number(forecastRevenue.toFixed(2)),

      target_revenue:
        latestTarget,

      forecast_vs_target:
        Number(forecastVsTarget.toFixed(2)),

      forecast_status:
        forecastStatus
    }
  }
];

